import {previewMarkup,handlePreviewClick,handlePreviewInput,handlePreviewKeyboard,installPreviewGestures} from './previews.js';
installPreviewGestures();

const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icon=name=>`<span class="symbol" aria-hidden="true">${name}</span>`;
const link=(href,label,symbol='arrow_forward',classes='text-link')=>`<a class="${classes}" href="${href}">${label}${icon(symbol)}</a>`;
const main=document.querySelector('main');
const searchDialog=document.querySelector('#search-dialog');
const searchInput=document.querySelector('#global-search');
const demoDialog=document.querySelector('#demo-dialog');
let data,currentComponent,currentSection='overview',filter='all',catalogQuery='',toastTimer;
const collapsed=new Set();
const mobileQuery=matchMedia('(max-width:900px)');
function setSidebar(open,restoreFocus=true){
 document.body.classList.toggle('sidebar-open',open);
 const sidebar=document.querySelector('#sidebar');
 sidebar.inert=mobileQuery.matches&&!open;
 document.querySelector('.workspace').inert=open&&mobileQuery.matches;
 document.querySelector('.rail').inert=open&&mobileQuery.matches;
 document.querySelector('.mobile-header').inert=open&&mobileQuery.matches;
 document.querySelector('[data-action="sidebar"]').setAttribute('aria-expanded',String(open));
 if(open){sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-modal','true');sidebar.querySelector('.sidebar-close').focus();}
 else{sidebar.removeAttribute('role');sidebar.removeAttribute('aria-modal');if(restoreFocus&&mobileQuery.matches)document.querySelector('[data-action="sidebar"]').focus();}
}
mobileQuery.addEventListener('change',()=>setSidebar(false,false));
const categories={all:'Todos',actions:'Acciones',communication:'Comunicación',containment:'Contenedores',navigation:'Navegación',selection:'Selección',input:'Entrada'};
const sections=[['overview','info','Descripción'],['specs','tune','Especificaciones'],['api','code','API'],['accessibility','accessibility','Accesibilidad']];
const currentTheme=()=>document.documentElement.dataset.theme==='dark'?'dark':'light';
const normal=value=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const hashFor=(id,section='overview')=>`#/components/${id}/${section}`;

function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function openDemo(title,content){document.querySelector('#demo-dialog-content').innerHTML=`<h2 id="demo-title" style="font-size:28px">${esc(title)}</h2>${content}<button class="icon-button" style="position:absolute;right:10px;top:10px" data-demo="close-modal" aria-label="Cerrar diálogo">${icon('close')}</button>`;if(!demoDialog.open)demoDialog.showModal();}
function closeDemo(){demoDialog.close();}
function highlight(source){const pattern=/\/\/[^\n]*|'(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*"|\b(?:import|from|export|default|function|return|const|let|if|true|false|new|type)\b/g;let result='',last=0;for(const match of source.matchAll(pattern)){result+=esc(source.slice(last,match.index));const token=match[0];result+=`<span class="${token.startsWith('//')?'syntax-comment':token.startsWith("'")||token.startsWith('"')?'syntax-string':'syntax-key'}">${esc(token)}</span>`;last=match.index+token.length;}return result+esc(source.slice(last));}
function codeCard(source,label='Example.tsx',download){return `<div class="code-card"><div class="code-header"><span>${icon('code')}${esc(label)}</span><div class="code-actions">${download?`<a href="${download}" download aria-label="Descargar ejemplo ${esc(label)}">${icon('download')}Descargar</a>`:''}<button type="button" data-action="copy" aria-label="Copiar código">${icon('content_copy')}Copiar</button></div></div><pre tabindex="0"><code>${highlight(source)}</code></pre></div>`;}
const callout=(title,message,symbol='info')=>`<div class="callout">${icon(symbol)}<div><strong>${title}</strong><p>${message}</p></div></div>`;
const table=(rows)=>`<div class="table-scroll"><table class="spec-table"><thead><tr><th>Referencia</th><th>Implementación local</th></tr></thead><tbody>${rows.map(([a,b])=>`<tr><td>${esc(a)}</td><td>${esc(b)}</td></tr>`).join('')}</tbody></table></div>`;
function renderSidebar(){
 const c=currentComponent;let html=`<a class="tree-link tree-root ${!c&&(!location.hash||location.hash==='#/components')?'active':''}" href="#/components">Todos los componentes</a>`;
 let group;
 for(const entry of data.components){
  if(entry.group!==group){if(group)html+='</div>';group=entry.group;if(group){const title=data.groups.find(g=>g.id===group).title;const expanded=!collapsed.has(group)||c?.group===group;html+=`<button type="button" class="tree-group" data-action="group" data-group="${group}" aria-expanded="${expanded}" aria-controls="tree-${group}">${esc(title)}${icon('expand_more')}</button><div class="tree-children" id="tree-${group}" ${expanded?'':'hidden'}>`;}}
  html+=`<a class="tree-link ${c?.id===entry.id?'active':''}" href="${hashFor(entry.id)}" ${c?.id===entry.id?'aria-current="page"':''}>${esc(entry.title)}</a>`;
 }
 if(group)html+='</div>';
 document.querySelector('#component-navigation').innerHTML=html;
}
function updateTheme(){
 const dark=currentTheme()==='dark';document.querySelectorAll('[data-action="theme"]').forEach(b=>{b.setAttribute('aria-label',dark?'Activar tema claro':'Activar tema oscuro');b.querySelector('.symbol').textContent=dark?'light_mode':'dark_mode';});
 const reduced=document.documentElement.dataset.reduced==='true';document.querySelectorAll('[data-action="motion"]').forEach(b=>{b.setAttribute('aria-pressed',String(reduced));b.setAttribute('aria-label',reduced?'Activar animaciones':'Reducir animaciones');b.querySelector('.symbol').textContent=reduced?'play_arrow':'pause';});
 document.querySelector('meta[name="theme-color"]').content=dark?'#141218':'#fef7ff';
}
function showCatalog(){
 currentComponent=undefined;
 main.innerHTML=`<div class="page-heading"><div class="eyebrow">${icon('widgets')}MATERIAL 3, EN REACT NATIVE</div><h1>Componentes</h1><p class="intro">Pequeñas piezas. Grandes posibilidades.<br>Explora los componentes de Mobile Design y construye interfaces con una misma forma de sentirse.</p></div>
 <section class="showcase" aria-label="Explora Mobile Design"><div class="showcase-copy"><p class="eyebrow">EXPRESIÓN EN CADA DETALLE</p><h2 class="text-balance">Diseña para<br>sentirse bien.</h2>${link('#/start','Empieza con Mobile Design')}</div><div class="showcase-art"><div class="art-orbit" aria-hidden="true"></div><div class="art-flower" aria-hidden="true">${icon('star')}</div><div class="art-play"><div class="art-play-title"><span>${icon('music_note')}</span><span>Un poco de buen ritmo</span></div><div class="art-play-controls">${`<button class="icon-button" data-demo="command" aria-label="Canción anterior">${icon('skip_previous')}</button>`}<button class="md-button" data-demo="play">${icon('play_arrow')}Reproducir</button><button class="icon-button" data-demo="command" aria-label="Siguiente canción">${icon('skip_next')}</button></div></div><div class="art-slider"><p><span>A tu ritmo</span><span>♪</span></p><input type="range" min="0" max="100" value="65" aria-label="Volumen de demostración"></div><div class="art-dot" aria-hidden="true"></div></div></section>
 <section id="explore"><div class="section-top"><h2>Encuentra tu siguiente pieza</h2><label class="page-filter-search">${icon('search')}<input type="search" id="catalog-filter" value="${esc(catalogQuery)}" placeholder="Filtrar componentes" aria-label="Filtrar componentes"></label></div><div class="filter-bar" aria-label="Categorías">${Object.entries(categories).map(([key,label])=>`<button type="button" class="filter-chip ${filter===key?'active':''}" data-action="filter" data-filter="${key}" aria-pressed="${filter===key}">${filter===key?icon('check'):''}${label}</button>`).join('')}</div><p class="component-count" id="component-count"></p><div class="catalog-grid" id="catalog-grid"></div></section>`;
 updateCatalog();
}
function updateCatalog(){
 const query=normal(catalogQuery);
 const entries=data.components.filter(c=>(filter==='all'||c.category===filter)&&normal([c.title,...c.searchAliases,...c.variants,...c.exports].join(' ')).includes(query));
 document.querySelector('#component-count').textContent=`${entries.length} ${entries.length===1?'componente':'componentes'} · en el orden de Material 3`;
 document.querySelector('#catalog-grid').innerHTML=entries.length?entries.map(c=>`<a class="component-card" href="${hashFor(c.id)}" aria-label="Ver ${esc(c.title)}"><div class="card-preview" aria-hidden="true" inert>${previewMarkup(c.id,{staticView:true})}</div><div class="card-content"><h3>${esc(c.title)}</h3><p>${esc(c.tagline)}</p>${icon('arrow_outward')}</div></a>`).join(''):`<div class="empty-state">${icon('search')}<h3>No encontramos esa pieza</h3><p>Prueba con otro nombre o selecciona «Todos».</p><button class="md-button tonal" data-action="reset-filter">Limpiar filtros</button></div>`;
}
function demoPanel(c){return `<div class="demo-panel ${['carousel','navigation-drawer','date-pickers'].includes(c.id)?'large':''}"><div class="demo-toolbar"><span>${icon('smartphone')}Vista interactiva</span><div class="demo-actions"><button class="icon-button" data-action="reset-demo" aria-label="Restablecer demostración">${icon('refresh')}</button><button class="icon-button" data-action="theme" aria-label="Cambiar tema">${icon(currentTheme()==='dark'?'light_mode':'dark_mode')}</button></div></div><div class="demo-canvas">${previewMarkup(c.id)}</div></div><p class="demo-caption">${icon('info')}Representación web para explorar el patrón. El código de abajo utiliza el componente React Native del paquete.</p>`;}
function references(c){const base=c.reference.replace(/\/overview$/,'');return `<section class="doc-section" id="references"><h2>Referencias</h2><p>Consulta la guía original de Material Design 3 junto con la API de esta implementación.</p><div class="reference-grid">${[['overview','info','Overview'],['specs','tune','Specs'],['guidelines','description','Guidelines'],['accessibility','accessibility','Accessibility']].map(([slug,symbol,label])=>`<a class="reference-card" href="${base}/${slug}" target="_blank" rel="noopener noreferrer">${icon(symbol)}${label}${icon('open_in_new')}</a>`).join('')}</div></section>`;}
function nativeEvidence(c){return `<details class="native-evidence"><summary>${icon('smartphone')}Ver captura nativa verificada en iOS</summary><div class="native-evidence-content"><a href="./native/${c.id}.png" target="_blank" rel="noopener"><img src="./native/${c.id}.png" alt="Galería ${esc(c.title)} en iPhone 18 Pro Max, tema claro" loading="lazy" width="260"></a><div><p><strong>${esc(c.title)} · iOS 27.0</strong><br>Captura de la revisión del 2 de noviembre de 2026. Registra el estado visible de la galería en el simulador.</p><p>La captura nativa y la demostración web son evidencias distintas. El alcance por interacción se documenta en la verificación.</p>${link('#/verification','Ver alcance de las pruebas')}</div></div></details>`;}
function overview(c){return `<section class="doc-section" id="in-action">${demoPanel(c)}</section><section class="doc-section" id="when"><h2>Cuándo usarlo</h2><p>${esc(c.guidance)}</p></section><section class="doc-section" id="variants"><h2>Variantes</h2>${c.variants.length?`<p>Variantes documentadas en el catálogo local.</p><div class="variant-grid">${c.variants.map(v=>`<span class="variant-tag">${esc(v)}</span>`).join('')}</div>`:`<p>Esta familia no se divide en variantes. Sus estados y opciones se describen como configuraciones.</p>`}${c.configurations?.length?`<h3 style="margin-top:30px">Configuraciones y estados</h3><div class="tag-row">${c.configurations.map(v=>`<span class="pill">${esc(v)}</span>`).join('')}</div>`:''}</section><section class="doc-section" id="example"><h2>Úsalo en tu app</h2><p>Ejemplo completo y controlado, comprobado con TypeScript contra la versión local <code>${esc(data.version)}</code>. Requiere el proveedor de Mobile Design.</p>${codeCard(c.example,c.primaryExport+'.tsx','./examples/'+c.id+'.tsx')}${nativeEvidence(c)}</section>${references(c)}`;}
function specs(c){const configRows=c.api.filter(p=>/^(size|sizeClass|width|height|minimum|maximum|orientation|alignment|variant|shape|thickness|density|textAlign|edgePadding)/.test(p.name)).map(p=>[p.name,p.type.replace(/ \| undefined$/,'')]);return `<section class="doc-section" id="anatomy"><h2>Anatomía y configuración</h2><p>${esc(c.description)} La API local distingue variantes de configuraciones, estados y composiciones.</p><div class="tag-row">${c.exports.map(name=>`<span class="pill">${icon('code')}${esc(name)}</span>`).join('')}</div></section><section class="doc-section" id="dimensions"><h2>Dimensiones</h2>${c.dimensions.length?`<p>Medidas de la implementación, en unidades lógicas de React Native. El contenido y el texto del sistema pueden exigir adaptación.</p>${table(c.dimensions)}`:`<p>El tamaño se resuelve con el contenido y las propiedades admitidas. Consulta las especificaciones oficiales para la anatomía normativa; la tabla siguiente muestra las opciones reales del paquete.</p>`}${configRows.length?table(configRows):''}</section><section class="doc-section" id="tokens"><h2>Tema y estados</h2><p>El componente recibe los roles semánticos, la tipografía y el movimiento del proveedor compartido. Los ejemplos de esta documentación usan MD3 Baseline.</p>${table([['Color','Roles del tema claro u oscuro'],['Tipografía','Roboto y escala tipográfica Material'],['Iconos','Material Symbols Rounded'],['Movimiento','Preferencia de sistema y configuración del proveedor']])}${link('#/styles','Explorar los fundamentos de estilo')}</section>${references(c)}`;}
function apiRow(prop){const type=prop.type;return `<tr data-prop="${esc(prop.name)}"><td><code>${esc(prop.name)}</code>${prop.required?'<span class="required">REQUERIDA</span>':''}</td><td class="api-type">${type.length>110?`<details><summary><code>${esc(type.slice(0,100))}…</code></summary><code>${esc(type)}</code></details>`:`<code>${esc(type)}</code>`}${prop.description?`<p class="prop-description">${esc(prop.description)}</p>`:''}</td></tr>`;}
function api(c){return `<section class="doc-section" id="import"><h2>Importación</h2>${codeCard(`import { ${c.primaryExport} } from 'mobile-design';`,c.primaryExport+'.tsx')}<p>Exportaciones relacionadas: ${c.exports.map(s=>`<code>${esc(s)}</code>`).join(', ')}.</p></section><section class="doc-section" id="properties"><div class="section-top"><h2>Propiedades</h2><label class="page-filter-search">${icon('search')}<input type="search" id="api-filter" placeholder="Buscar propiedad" aria-label="Buscar propiedad"></label></div><p>Tabla generada desde los tipos TypeScript del componente <code>${esc(c.primaryExport)}</code>. Incluye propiedades propias y una selección de las heredadas de sus primitivas.</p><div class="table-scroll"><table class="api-table"><thead><tr><th>Propiedad</th><th>Tipo y descripción</th></tr></thead><tbody>${c.api.map(apiRow).join('')}</tbody></table></div><p class="responsive-note" id="api-count">${c.api.length} propiedades · generado el ${data.generated}</p></section><section class="doc-section" id="example"><h2>Ejemplo completo</h2>${codeCard(c.example,c.primaryExport+'.tsx','./examples/'+c.id+'.tsx')}</section>`;}
function accessibility(c){return `<section class="doc-section" id="semantics"><h2>Semántica e interacción</h2><p>${esc(c.accessibility)}</p>${callout('El estado también se comunica', 'Incluye nombre, valor y disponibilidad. El color, el icono y la animación complementan esa información; el lector debe poder entender la acción.')}</section><section class="doc-section" id="focus"><h2>Foco, texto y movimiento</h2><ul class="check-list"><li>${icon('check')}Mantén una secuencia de foco coherente con el orden del contenido.</li><li>${icon('check')}Comprueba las etiquetas y acciones con texto ampliado.</li><li>${icon('check')}Respeta la preferencia de movimiento reducido.</li><li>${icon('check')}Conserva nombres accesibles para los controles que sólo muestran iconos.</li></ul><p>Estas pautas deben revisarse también en la pantalla que compone el componente y sus acciones.</p></section><section class="doc-section" id="coverage"><h2>Qué se verificó</h2><p>Las 36 galerías se revisaron en ambos temas y con movimiento reducido. Los recorridos de VoiceOver y texto ampliado cubren los casos representativos nombrados en el informe, sin declarar cobertura de todas las combinaciones.</p>${link('#/verification','Ver evidencia y límites de verificación')}${nativeEvidence(c)}</section>${references(c)}`;}
function renderComponent(c,section){
 const active=sections.some(s=>s[0]===section)?section:'overview';currentComponent=c;currentSection=active;
 const toc={overview:[['in-action','En acción'],['when','Cuándo usarlo'],['variants','Variantes'],['example','Uso en React Native'],['references','Referencias']],specs:[['anatomy','Anatomía'],['dimensions','Dimensiones'],['tokens','Tema y estados'],['references','Referencias']],api:[['import','Importación'],['properties','Propiedades'],['example','Ejemplo completo']],accessibility:[['semantics','Semántica'],['focus','Foco y movimiento'],['coverage','Verificación'],['references','Referencias']]};
 const i=data.components.indexOf(c),prev=data.components[i-1],next=data.components[i+1];
 main.innerHTML=`<div class="detail-heading page-heading"><div class="eyebrow">${icon(c.icon)}${esc(categories[c.category])} <span style="opacity:.45">/</span> ${esc(c.searchAliases[0]??c.title)}</div><h1>${esc(c.title)}</h1><p class="intro">${esc(c.description)}</p></div><div class="detail-layout"><div><nav class="component-tabs" aria-label="Secciones de ${esc(c.title)}">${sections.map(([id,symbol,label])=>`<a href="${hashFor(c.id,id)}" class="${id===active?'active':''}" ${id===active?'aria-current="page"':''}>${icon(symbol)}${label}</a>`).join('')}</nav>${({overview,specs,api,accessibility}[active])(c)}<nav class="next-prev" aria-label="Componentes anterior y siguiente">${prev?`<a href="${hashFor(prev.id)}">${icon('arrow_back')}<span><small>ANTERIOR</small>${esc(prev.title)}</span></a>`:'<span></span>'}${next?`<a href="${hashFor(next.id)}"><span><small>SIGUIENTE</small>${esc(next.title)}</span>${icon('arrow_forward')}</a>`:'<span></span>'}</nav></div><aside class="toc" aria-label="En esta página"><p>En esta página</p>${toc[active].map(([id,label])=>`<a href="#${id}" data-scroll-to="${id}">${label}</a>`).join('')}</aside></div>`;
}
const providerExample=`import { GestureHandlerRootView } from 'react-native-gesture-handler';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import { MobileDesignProvider, Button } from 'mobile-design';

export default function App() {
  return (
    <GestureHandlerRootView style={{ flex: 1 }}>
      <SafeAreaProvider>
        <MobileDesignProvider colorScheme="light" motion="expressive">
          <Button onPress={() => console.log('Hola, Mobile Design')}>
            Empezar
          </Button>
        </MobileDesignProvider>
      </SafeAreaProvider>
    </GestureHandlerRootView>
  );
}`;
function startPage(){currentComponent=undefined;main.innerHTML=`<div class="guide-layout"><div class="page-heading"><div class="eyebrow">${icon('code')}COMENZAR</div><h1>De la idea<br>a la interfaz.</h1><p class="intro">Una base compartida de componentes, colores y movimiento para construir tu app con React Native.</p></div><div class="guide-grid"><article class="guide-card">${icon('widgets')}<h3>36 familias, un sistema</h3><p>Componentes con variantes, estados y acciones coordinadas con el tema de la app.</p>${link('#/components','Explorar componentes')}</article><article class="guide-card">${icon('palette')}<h3>Una identidad compartida</h3><p>Roboto, Material Symbols y roles semánticos de color desde un único proveedor.</p>${link('#/styles','Conocer los estilos')}</article></div><section class="doc-section"><span class="step-number">1</span><h2>Conecta el paquete local</h2><p>Mobile Design <code>${data.version}</code> es un paquete privado del workspace. La documentación corresponde a esa implementación; todavía no hay una distribución pública en npm.</p>${codeCard(`// package.json de tu app dentro del workspace\n{\n  "dependencies": {\n    "mobile-design": "workspace:*"\n  }\n}`, 'package.json')}${codeCard('pnpm install','Terminal')}<p>La aplicación del workspace ya declara estas dependencias. Para otro consumidor, instala versiones compatibles antes de enlazar el paquete.</p></section><section class="doc-section"><span class="step-number">2</span><h2>Prepara el proveedor</h2><p><code>MobileDesignProvider</code> comparte el tema, el contexto de Paper, los iconos y las fuentes incluidas. Las superficies con gestos necesitan el root de Gesture Handler.</p>${codeCard(providerExample,'App.tsx')}</section><section class="doc-section"><span class="step-number">3</span><h2>Elige tu primera pieza</h2><p>Usa el estado de tu pantalla para controlar selección, texto y apertura. Cada ficha incluye un módulo completo que puedes copiar o descargar.</p><div class="reference-grid">${['buttons','text-fields','tabs','lists'].map(id=>{const c=data.components.find(c=>c.id===id);return `<a class="reference-card" href="${hashFor(id)}">${icon(c.icon)}${c.title}${icon('arrow_forward')}</a>`}).join('')}</div></section><section class="doc-section"><h2>Compatibilidad del paquete</h2><p>Requisitos declarados en <code>mobile-design/package.json</code>. La revisión nativa se ejecutó en la combinación registrada en Verificación.</p>${table(Object.entries(data.peers))}</section></div>`;}
function hex(color){const match=color.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);return match?'#'+match.slice(1,4).map(v=>Number(v).toString(16).padStart(2,'0')).join('').toUpperCase():color;}
function stylesPage(){currentComponent=undefined;const colors=data.colors[currentTheme()];const palette=[['primary','onPrimary','Primary'],['primaryContainer','onPrimaryContainer','Primary container'],['secondary','onSecondary','Secondary'],['secondaryContainer','onSecondaryContainer','Secondary container'],['tertiary','onTertiary','Tertiary'],['tertiaryContainer','onTertiaryContainer','Tertiary container'],['surface','onSurface','Surface'],['surfaceContainer','onSurface','Surface container'],['error','onError','Error']];main.innerHTML=`<div class="guide-layout"><div class="page-heading"><div class="eyebrow">${icon('palette')}FUNDAMENTOS DE ESTILO</div><h1>Una misma<br>personalidad.</h1><p class="intro">Color, tipografía, formas y movimiento. Las decisiones compartidas que conectan cada componente.</p></div><section class="doc-section" id="color"><div class="section-top"><h2>Color con significado</h2><button class="md-button tonal" data-action="theme">${icon(currentTheme()==='dark'?'light_mode':'dark_mode')}Cambiar tema</button></div><p>La paleta predeterminada es <strong>MD3 Baseline</strong>. Estos valores se sincronizan desde la salida canónica del paquete; toca un color para copiarlo.</p><div class="palette-grid">${palette.map(([role,onRole,label])=>`<button class="swatch" data-action="copy-color" data-color="${esc(hex(colors[role]))}" aria-label="Copiar ${label}, ${hex(colors[role])}" style="background:${colors[role]};color:${colors[onRole]}"><strong>${label}</strong><code>${hex(colors[role])}</code>${icon('content_copy')}</button>`).join('')}</div>${codeCard(`import { createMobileDesignTheme, MobileDesignProvider } from 'mobile-design';\n\nconst theme = createMobileDesignTheme({\n  colorScheme: '${currentTheme()}',\n  motion: 'expressive',\n});\n\n// El proveedor también admite colorScheme y motion directamente.\n<MobileDesignProvider theme={theme}>\n  {/* Tu aplicación */}\n</MobileDesignProvider>`,'theme.tsx')}<p>En el workspace, <code>pnpm theme:generate md3-baseline</code> genera los roles compartidos de la app. Una semilla HEX puede generar otra paleta sin cambiar las APIs de los componentes.</p></section><section class="doc-section" id="typography"><h2>Roboto, de principio a fin</h2><p>La escala Material organiza los textos por su función. Las fuentes están incluidas en Mobile Design y se cargan desde el proveedor.</p>${[['Display','displayLarge','57 / 64',57],['Headline','headlineMedium','28 / 36',28],['Title','titleLarge','22 / 28',22],['Body','bodyLarge','16 / 24',16],['Label','labelLarge','14 / 20',14]].map(([label,token,metric,size])=>`<div class="type-sample"><span style="font-size:${size}px;line-height:1.2">${label} · Haz espacio para lo importante.</span><small>${token} · ${metric}</small></div>`).join('')}${codeCard(`import { Text } from 'mobile-design';\n\n<Text variant="headlineMedium">Tu biblioteca</Text>\n<Text variant="bodyLarge">Todo lo que quieres volver a escuchar.</Text>`,'Typography.tsx')}</section><section class="doc-section" id="icons"><h2>Material Symbols Rounded</h2><p>Los iconos comparten el lenguaje visual del sistema. Los controles sin texto necesitan un nombre accesible.</p><div class="preview-row" style="justify-content:flex-start;gap:20px;padding:20px 0">${['search','arrow_back','close','favorite','bookmark','music_note','more_vert'].map(name=>`<span style="background:var(--surface-container);border-radius:16px;padding:16px">${icon(name)}</span>`).join('')}</div>${codeCard(`import { IconButton, MaterialSymbol } from 'mobile-design';\n\n<MaterialSymbol name="search" size={24} />\n<IconButton icon="magnify" accessibilityLabel="Buscar música"\n  onPress={() => console.log('Buscar')} />`,'Icons.tsx')}</section><section class="doc-section" id="shape"><h2>Formas con intención</h2><p>Las esquinas siguen los tokens del tema y la función del componente. La forma puede responder a presión y selección.</p><div class="shape-row">${[[4,'Extra small'],[8,'Small'],[12,'Medium'],[16,'Large'],[28,'Extra large']].map(([radius,label])=>`<div class="shape-tile" style="border-radius:${radius}px">${label}</div>`).join('')}</div><p class="responsive-note">Muestra visual de radios. Las medidas específicas de cada componente se documentan en su ficha.</p></section><section class="doc-section" id="motion"><h2>Movimiento que acompaña</h2><p>El proveedor permite elegir movimiento estándar o expresivo. La reducción de movimiento del sistema conserva el significado de los estados.</p>${codeCard(`<MobileDesignProvider motion="expressive" reduceMotion="auto">\n  {/* Tu aplicación */}\n</MobileDesignProvider>`,'Motion.tsx')}<button class="md-button tonal" data-action="motion">${icon('pause')}Alternar movimiento de la documentación</button></section></div>`;}
function verificationPage(){currentComponent=undefined;const v=data.verification;main.innerHTML=`<div class="guide-layout"><div class="page-heading"><div class="eyebrow">${icon('verified')}REVISIÓN DEL 2 DE NOVIEMBRE DE 2026</div><h1>Detalles<br>que se revisan.</h1><p class="intro">El estado de verificación de Mobile Design, con evidencia concreta y un alcance explícito.</p></div><div class="stats-grid"><div class="verification-stat"><b>${v.families}</b><span>familias en la matriz iOS</span></div><div class="verification-stat"><b>${v.automatic}/37</b><span>bloques automáticos aprobados</span></div><div class="verification-stat"><b>${v.nativeCases}</b><span>casos nativos finales aprobados</span></div></div><section class="doc-section"><h2>Qué cubre la revisión</h2><ul class="check-list"><li>${icon('check_circle')}36 galerías con capturas claras/oscuras y movimiento reducido.</li><li>${icon('check_circle')}12 acciones adicionales: presión, cancelación, selección, teclado, navegación, gestos y cargas.</li><li>${icon('check_circle')}${v.voiceOver} recorridos con VoiceOver real y ${v.largeText} casos con texto del sistema ampliado.</li><li>${icon('check_circle')}TypeScript y contratos automáticos; 33 casos de selección/ciclo de vida.</li><li>${icon('check_circle')}Confirmación de Time picker con texto normal/ampliado y superficies de temas asentadas.</li></ul></section><section class="doc-section"><h2>Cómo leer estos resultados</h2><p>Se consolidó el último intento aprobado de cada caso. Los fallos del ejecutor y sus reintentos quedaron registrados. Las capturas nativas de cada galería están disponibles en su ficha, bajo «Uso en React Native».</p>${callout('Una captura acredita un estado concreto','No significa que se hayan probado todas las variantes, cada clip de referencia o todas sus combinaciones en cualquier dispositivo.')}</section><section class="doc-section"><h2>Correcciones al ejecutar</h2>${table([['Chip','Identidades distintas para las regiones primaria y de cierre.'],['TimePicker','Alineación tipográfica y de acciones con texto ampliado.'],['Ejemplo de Progress','Concepto e importe agrupados para lectura accesible.'],['Galerías','Insets de teclado adaptados en iOS.']])}</section><section class="doc-section"><h2>Entorno y límites</h2><p>App de desarrollo en simuladores iOS 27.0: iPhone 18 Pro Max y un iPhone 17e temporal para texto ampliado. No se ejecutó Android en este cierre.</p><p>Se recogieron métricas de CPU y memoria durante scroll, sin baseline de producción. Xcode no devolvió una serie de FPS o hitches. El iPhone físico estaba desconectado al cierre.</p><p>La publicación de esta documentación no añade una certificación universal de conformidad MD3. Las adaptaciones conocidas de movimiento, física y geometría deben evaluarse en la pantalla que utiliza el componente.</p></section></div>`;}
function route(){
 if(!data)return;
 const [page='components',id,section='overview']=(location.hash.startsWith('#/')?location.hash.slice(2):'components').split('/');
 const component=page==='components'&&id?data.components.find(c=>c.id===id):undefined;
 if(component)renderComponent(component,section);else if(page==='start')startPage();else if(page==='styles')stylesPage();else if(page==='verification')verificationPage();else showCatalog();
 const selected=['start','styles','verification'].includes(page)?page:'components';
 document.querySelectorAll('[data-rail]').forEach(a=>{const active=a.dataset.rail===selected;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 document.querySelector('#breadcrumbs').innerHTML=`<a href="#/components">Documentación</a><span>/</span>${component?`<a href="#/components">Componentes</a><span>/</span>${esc(component.title)}`:({start:'Comenzar',styles:'Estilos',verification:'Verificación'}[page]??'Componentes')}`;
 document.title=(component?.title??({start:'Comenzar',styles:'Estilos',verification:'Verificación'}[page]??'Componentes'))+' · Mobile Design';
 setSidebar(false,false);
 renderSidebar();updateTheme();window.scrollTo({top:0,behavior:'instant'});
}
function renderSearch(){const query=normal(searchInput.value);const results=data.components.filter(c=>normal([c.title,...c.searchAliases,...c.variants,...c.configurations??[],...c.exports,...c.api.map(p=>p.name)].join(' ')).includes(query)).slice(0,12);document.querySelector('#search-results').innerHTML=results.length?results.map(c=>`<a class="search-result" href="${hashFor(c.id)}" data-action="search-result">${icon(c.icon)}<span><strong>${esc(c.title)}</strong><small>${esc(c.searchAliases[0]??categories[c.category])} · ${esc(c.exports[0])}</small></span>${icon('arrow_forward')}</a>`).join(''):`<div class="search-empty">${icon('search')}<p>No encontramos resultados para «${esc(searchInput.value)}».</p><small>Prueba «botones», «tabs» o el nombre de una propiedad.</small></div>`;}
function openSearch(){if(!data)return;searchInput.value='';renderSearch();searchDialog.showModal();searchInput.focus();}
async function copyText(value){try{await navigator.clipboard.writeText(value);toast('Copiado al portapapeles');return true;}catch{toast('No se pudo copiar. Puedes seleccionar el texto del ejemplo.');return false;}}
document.addEventListener('click',async event=>{
 if(event.target.closest('.skip-link')){event.preventDefault();main.focus();main.scrollIntoView({behavior:'instant'});return;}
 const scrollLink=event.target.closest('[data-scroll-to]');if(scrollLink){event.preventDefault();document.getElementById(scrollLink.dataset.scrollTo)?.scrollIntoView({behavior:document.documentElement.dataset.reduced==='true'?'instant':'smooth'});return;}
 const control=event.target.closest('[data-action]');
 if(control){switch(control.dataset.action){
  case'search':openSearch();break;
  case'close-search':searchDialog.close();break;
  case'search-result':searchDialog.close();break;
  case'sidebar':setSidebar(!document.body.classList.contains('sidebar-open'));break;
  case'close-sidebar':setSidebar(false);break;
  case'theme':document.documentElement.dataset.theme=currentTheme()==='dark'?'light':'dark';try{localStorage.setItem('md-docs-theme',currentTheme())}catch{}if(location.hash==='#/styles')stylesPage();updateTheme();break;
  case'motion':document.documentElement.dataset.reduced=String(document.documentElement.dataset.reduced!=='true');try{localStorage.setItem('md-docs-reduced',document.documentElement.dataset.reduced)}catch{}updateTheme();break;
  case'group':{const group=control.dataset.group;const expanded=control.getAttribute('aria-expanded')==='true';if(expanded)collapsed.add(group);else collapsed.delete(group);control.setAttribute('aria-expanded',String(!expanded));document.querySelector('#tree-'+group).hidden=expanded;break;}
  case'filter':filter=control.dataset.filter;document.querySelectorAll('[data-action="filter"]').forEach(button=>{const selected=button===control;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected));button.querySelector('.symbol')?.remove();if(selected)button.insertAdjacentHTML('afterbegin',icon('check'));});updateCatalog();break;
  case'reset-filter':filter='all';catalogQuery='';showCatalog();break;
  case'copy':await copyText(control.closest('.code-card').querySelector('code').textContent);break;
  case'copy-color':await copyText(control.dataset.color);break;
  case'reset-demo':control.closest('.demo-panel').querySelector('.demo-canvas').innerHTML=previewMarkup(currentComponent.id);toast('Demostración restablecida');break;
 }}else handlePreviewClick(event.target,{toast,openDemo,closeDemo});
});
document.addEventListener('input',event=>{if(event.target.id==='global-search')renderSearch();else if(event.target.id==='catalog-filter'){catalogQuery=event.target.value;updateCatalog();}else if(event.target.id==='api-filter'){const query=normal(event.target.value);let count=0;main.querySelectorAll('[data-prop]').forEach(row=>{row.hidden=!normal(row.dataset.prop).includes(query);if(!row.hidden)count++;});document.querySelector('#api-count').textContent=`${count} propiedades`; }else if(event.target.dataset.demoInput)handlePreviewInput(event.target);});
document.addEventListener('keydown',event=>{
 if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(searchDialog.open)searchDialog.close();else openSearch();}
 if(event.key==='Escape'&&document.body.classList.contains('sidebar-open'))setSidebar(false);
 if(event.key==='Tab'&&document.body.classList.contains('sidebar-open')){const nodes=[...document.querySelector('#sidebar').querySelectorAll('button:not([hidden]),a[href]')].filter(el=>el.getBoundingClientRect().height>0&&!el.closest('[hidden]'));const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
 if(event.key==='Enter'&&searchDialog.open&&document.activeElement===searchInput){const first=searchDialog.querySelector('.search-result');if(first){event.preventDefault();first.click();}}
 if(searchDialog.open&&['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();const links=[...searchDialog.querySelectorAll('.search-result')];if(!links.length)return;const i=links.indexOf(document.activeElement);links[(i+(event.key==='ArrowDown'?1:-1)+links.length)%links.length].focus();}
 handlePreviewKeyboard(event);
});
for(const dialog of [searchDialog,demoDialog])dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
window.addEventListener('hashchange',route);
try{data=JSON.parse(document.querySelector('#documentation-data').textContent);route();}catch(error){main.innerHTML=`<div class="empty-state"><h1>Un momento…</h1><p>No pudimos cargar la documentación. Recarga la página o sincroniza de nuevo el sitio.</p><button class="md-button" onclick="location.reload()">Reintentar</button></div>`;console.error(error);}
